def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        base = DAILY_SALARY * 0.25
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.6
        return max(0.0, min(budget, base))

    pressure_bids = []
    eric_bid = None
    desperate_opp = 0
    rich_opp = 0
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            pressure_bids.append(prev['bid'])
            if agent_id == 'Eric':
                eric_bid = prev['bid']
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        if opp.get('budget', 0) >= 200:
            rich_opp += 1

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    base = DAILY_SALARY * 0.42

    if loose_supply:
        base = DAILY_SALARY * 0.28
    elif tight_supply:
        base = DAILY_SALARY * 0.72

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.92)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.78)

    if pressure_bids:
        highest_prev = max(pressure_bids)
        avg_prev = sum(pressure_bids) / float(len(pressure_bids))
        if highest_prev >= 100:
            if hp > 4 and not tight_supply:
                base = min(base, DAILY_SALARY * 0.35)
            else:
                base = max(base, DAILY_SALARY * 0.82)
        elif avg_prev >= 60:
            base = max(base, DAILY_SALARY * 0.62)
        else:
            base = max(base, min(DAILY_SALARY * 0.58, highest_prev + 2.0))

    if eric_bid is not None:
        if eric_bid >= 110:
            if hp > 4 and not tight_supply:
                base = min(base, DAILY_SALARY * 0.32)
            else:
                base = max(base, DAILY_SALARY * 0.8)
        elif eric_bid >= 85:
            if tight_supply or hp <= 4:
                base = max(base, DAILY_SALARY * 0.76)
            else:
                base = min(max(base, eric_bid * 0.72), DAILY_SALARY * 0.68)
        else:
            base = max(base, eric_bid + 3.0)

    if desperate_opp >= 2 and hp >= 5 and not tight_supply:
        base = min(base, DAILY_SALARY * 0.33)

    if rich_opp >= 2 and tight_supply:
        base = max(base, DAILY_SALARY * 0.84)

    if day >= 8:
        if hp >= 5:
            base = min(max(base, DAILY_SALARY * 0.5), DAILY_SALARY * 0.72)
        else:
            base = max(base, DAILY_SALARY * 0.82)

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget * 0.7)
    elif budget > 500 and hp <= 4:
        base = max(base, DAILY_SALARY * 0.9)

    bid = max(0.0, min(budget, base))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer how aggressive the surviving opponents were.
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Pressure tiers from yesterday.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85  # ~76.5
    medium_pressure = (highest_prev_bid >= DAILY_SALARY * 0.55) and not high_pressure

    # Supply-based aggressiveness: with higher supply, we can bid less and still win water.
    # supply is between 15 and 25.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Core bid target
    if high_pressure:
        # If they were willing to pay near salary, we must contest.
        base = DAILY_SALARY * (0.35 + 0.25 * (1.0 - supply_ratio))  # higher when supply is low
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * (0.75 + 0.1 * (1.0 - supply_ratio))
        else:
            # Slightly overtake their last highest bid if we're safe.
            base = max(base, min(budget, highest_prev_bid + 2.0))
    elif medium_pressure:
        base = DAILY_SALARY * (0.45 + 0.2 * (1.0 - supply_ratio))
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * (0.7 + 0.1 * (1.0 - supply_ratio))
        else:
            base = max(base, highest_prev_bid * 0.95)
    else:
        # Low pressure: bid enough to avoid being starved.
        base = DAILY_SALARY * (0.55 - 0.15 * supply_ratio)
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.85

    # Convert to feasible bid within budget.
    # Ensure non-negative and do not exceed budget.
    bid = max(0.0, min(budget, float(base)))

    # If supply is minimal and my hp is critical, bid harder.
    if supply <= float(MIN_SUPPLY) + 0.5 and (hp <= 3 or no_water_days >= 2):
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid a minimal amount to secure water.
    if not alive_opponents:
        return min(my_status['budget'], 1)

    # Base bid: a competitive amount, slightly above observed averages of strong players.
    base_bid = DAILY_SALARY * 0.63 # 94.5

    # Look at yesterday's bids from all alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Adjust bid based on highest previous bid to try and outbid strong opponents.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        base_bid = max(base_bid, highest_prev_bid + 1)

    # HP-based aggressive bidding: If HP is low, bid very aggressively.
    bid = base_bid
    if my_status['hp'] <= 2:
        bid = max(bid, DAILY_SALARY * 0.95) # 142.5
    elif my_status['hp'] <= 4:
        bid = max(bid, DAILY_SALARY * 0.8)  # 120

    # Day-based adjustment: Increase bid aggressiveness in the late game if HP is not optimal.
    days_remaining = EPISODE_DAYS - day_context['day']
    if days_remaining <= 3 and my_status['hp'] <= 5:
        bid = max(bid, DAILY_SALARY * 0.9) # 135

    # Ensure bid does not exceed budget and is non-negative.
    final_bid = min(my_status['budget'], bid)
    return max(0, final_bid)

